recipes.code:
{
  "inputs": [
    {
      "id": "agent-ready-api-key",
      "type": "promptString",
      "description": "Agent Ready Pro API key for scan_site and get_scan. ask and validate_structured_data work without one. Issue a key at https://agent-ready.dev/dashboard/api-keys.",
      "password": true
    }
  ],
  "servers": {
    "agent-ready": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "agent-ready-mcp@0.7.2"
      ],
      "env": {
        "AGENT_READY_API_KEY": "${input:agent-ready-api-key}"
      }
    }
  }
}
